from pathlib import Path
import json,base64,mimetypes,html,re
from table_engine import R,M,T,variation,samples,render_sources
from additions04 import extend
from web04 import upgrade
palette=json.loads((R/'design/color_system.json').read_text());records=json.loads((R/'design/variation_records.json').read_text());panels=[]
def uri(p):
 p=R/p;return 'data:'+(mimetypes.guess_type(p.name)[0] or 'application/octet-stream')+';base64,'+base64.b64encode(p.read_bytes()).decode()
def img(p,alt,cls=''):return f'<img src="{uri(p)}" alt="{html.escape(alt)}" class="{cls}" loading="lazy">'
def dl(p,label):return f'<a download="{Path(p).name}" href="{uri(p)}">{label}</a>'
def why(s,source='Quy chuẩn 0.4 · áp dụng từ nguồn ZO Math'):return f'<p class="why"><span class="role-tag">Vì sao thiết kế như vậy</span>{s}</p><p class="source-line">Căn cứ: {source}</p>'
def card(title,body,reason,source='',stage=False):return f'<article class="specimen"><h3>{title}</h3>'+('<div class="image-stage">'+body+'</div>' if stage else body)+why(reason,source or 'Nguồn ZO Math và góp ý cho bản 0.4')+'</article>'
def panel(id,title,lead,body):panels.append((id,title,f'<section class="ds-panel" id="{id}"><div class="section-head"><span class="eyebrow">ZO Math / hệ thiết kế 0.4</span><h1>{title}</h1><p class="lead">{lead}</p></div>{body}</section>'))
panel('overview','Cùng một nhịp đọc.','Màu sắc của 0.2 được giữ nguyên. Bản 0.4 tổ chức lại cách các thành phần cùng xuất hiện: có phần dẫn, phần hỗ trợ và khoảng nghỉ.',f'<div class="hero"><div><h2>Nhận ra ZO.<br>Tập trung vào Toán.</h2><p>Logo nhẹ hơn. Hình vẽ cùng một ngôn ngữ. Bảng có cấu trúc thật. Nhãn lùi về vai trò nhắc nhỏ.</p><div class="download-row"><a class="button primary" href="r1_g01.html">Mở R1-G01 dùng thử</a>{dl("r1_g01.html","Tải riêng trang R1-G01")}</div><p class="smallprint">Trong gói ZIP, mở trang trực tiếp. Khi xem tệp HTML độc lập, dùng liên kết tải riêng để giữ trang R1-G01.</p>{img("logos/motif.svg","Dấu nhấn ZO","motif")}</div><div class="hero-art">{img("logos/stack_color.svg","Logo ZO Math cải tiến với ba màu đã chốt")}</div></div><div class="rule-list"><div><strong>Một nền chung</strong><p>Đỏ #EF5350 · vàng #FFCA28 · Xám ZO #3E3A35, cùng các tông đã chọn ở 0.2.</p></div><div><strong>Một vai trò cho mỗi nét</strong><p>Đối tượng, ngữ cảnh, đường phụ, điểm, nhãn và phần nhấn được phân biệt bằng ý nghĩa.</p></div><div><strong>Một trọng tâm mỗi vùng</strong><p>Nội dung dẫn; logo và dấu nhấn định vị; tag nhắc nhẹ; bảng giúp đối chiếu.</p></div></div>'+why('Bộ này là một hướng thiết kế thống nhất. Hai hệ logo dùng cùng hình chữ: bản một màu cho bối cảnh yên, bản ba màu cho nhận diện. Hệ bìa 0.2 được giữ để đối chiếu với hệ mới.','Góp ý trực tiếp ngày 06/10/2026'))
# Evidence and method
panel('research','Những gì được kế thừa, và những gì được sửa.','Quy chuẩn thiết kế được đối chiếu với cấu trúc học liệu thật, thay vì chỉ trưng các ô mẫu rời nhau.','<div class="rule-list"><div><strong>R1-G01 bản 06/10</strong><p>9 phần cấp hai; 1.469 biểu thức MathML có nguồn LaTeX; 13 bảng biến thiên, 13 đồ thị, 18 bảng nội dung. Giữ bài tập, đáp án, liên kết và các bản PDF nguồn.</p></div><div><strong>Đổi cách thể hiện</strong><p>13 bảng biến thiên lấy từ dữ liệu HTML đi kèm hình; xuất bảng HTML/Quarto và tabular LaTeX. BBT05 vẫn là ca sai có chủ ý trong bài tập.</p></div><div><strong>Đối chiếu bằng chứng</strong><p>W3C: quan hệ đầu hàng–cột; Quarto: bảng và ô có nội dung Markdown; LaTeX → MathML giữ công thức trong bảng thật; MDN: small caps và MathML.</p></div></div><ul><li><a href="https://www.w3.org/WAI/tutorials/tables/">W3C — cấu trúc và đầu bảng</a></li><li><a href="https://www.w3.org/WAI/tutorials/tables/tips/">W3C — cuộn bảng, nhấn hàng/cột</a></li><li><a href="https://quarto.org/docs/authoring/tables.html">Quarto — bảng và data-qmd</a></li><li><a href="https://katex.org/docs/options">KaTeX — đầu ra MathML từ LaTeX</a></li><li><a href="https://developer.mozilla.org/en-US/docs/Web/CSS/Reference/Properties/font-variant-caps">MDN — small caps</a></li></ul>'+why('Tài liệu chuẩn giúp kiểm cấu trúc, phép đo và khả năng triển khai; không tự chứng minh thiết kế đẹp. Các quyết định thị giác vẫn là đề xuất dành riêng cho ZO Math.'))
body='<div class="swatch-row">'+''.join(f'<div class="swatch" style="background:{v};color:{"#FBFAF8" if n=="Xám ZO" else "#25221F"}"><strong>{n}</strong><code>{v}</code></div>' for n,v in [('Đỏ ZO','#EF5350'),('Vàng ZO','#FFCA28'),('Xám ZO','#3E3A35')])+'</div>'
for fam,name in [('red','Đỏ'),('yellow','Vàng'),('gray','Xám ZO')]:body+='<h2>'+name+'</h2><div class="tonal-ramp">'+''.join(f'<div><i style="background:{v}"></i><small>{k}<br>{v.upper()}</small></div>' for k,v in palette['palette'].items() if k.startswith(fam))+'</div>'
body+=why('Bảng màu giống 0.2 từng mã. Thay đổi là phân vai rõ hơn: nền giấy làm trường chung; đỏ giữ điểm cần xem; vàng nhấn vùng/quan hệ; Xám ZO giữ chữ và cấu trúc. Đỏ 12 dành cho chữ nhỏ; đỏ 10 dành cho đồ họa và nhận diện.','color_system.json của 0.2 — giữ nguyên')+ '<div class="color-pair"><span class="role-tag">Khi cần nhấn trong bảng</span><p><strong>Hàng hoặc cột:</strong> yellow-1 #FFF9E9. <strong>Ô giao:</strong> yellow-2 #FFE9A9. <strong>Tổng:</strong> gray-2 #F8F5F0. <strong>Lỗi được xác định:</strong> red-1 #FDEDED kèm lời chỉ rõ lỗi.</p></div>'
panel('color','Màu đã chốt, vai trò được làm rõ.','Không mở thêm một bảng màu mới. Các tông của 0.2 được dùng tiết chế theo nhiệm vụ.',body)
body='<div class="gallery-grid">'
