body+='</div><h2>Thích ứng theo nền và kích thước</h2><div class="gallery-grid">'+card('Nền tối', '<div class="image-stage dark">'+img('logos/horizontal_color_dark.svg','Logo trên nền Xám ZO tối')+'</div>','MATH và biên O chuyển sáng; đỏ và vàng vẫn là hai màu nhận diện. Không đảo hoặc khoét chữ O để xử lí nền.')+card('Ảnh đại diện',img('logos/avatar_color.svg','Ảnh đại diện mới','mini-logo'),'Vùng bao bo nhẹ phục vụ biểu tượng ứng dụng; phần nhận diện không phụ thuộc vào khung. MATH được bỏ khi không đủ kích thước đọc.')+'</div><h3>Biểu tượng nhỏ, ở cỡ xuất thật</h3><div class="symbol-row">'+''.join(img(f'logos/favicon_color_{s}.png',f'ZO {s}px')+f'<small>{s}px</small>' for s in [16,24,32,48,64])+'</div>'+why('Biểu tượng nhỏ giữ ZO và bỏ MATH. 16 px là mẫu stress để đánh giá nhận ra; đề xuất dùng bản một màu nếu môi trường hiển thị làm O vàng yếu. Bản đứng nên từ 64 px, bản ngang từ 150 px; các ngưỡng này cần duyệt trên thiết bị thực.')+'<h2>Dấu nhấn vẫn là dấu nhấn ZO</h2>'+img('logos/motif.svg','Dấu nhấn đỏ vàng chuẩn','motif')+why('Không đổi tỉ lệ 15 : 1,75 : 8 hay thứ tự màu. Mỗi vùng chỉ dùng một lần có nhiệm vụ; không đặt cạnh một chi tiết đang nhấn cùng nội dung.','Dau_nhan_ZO_Quy_cach.md')
panel('identity','Nhẹ nét hơn, vẫn nhận ra ZO.','Hai hệ dùng một cấu trúc hình chữ. Logo ba màu được chọn để áp dụng; bản một màu là thành viên cùng hệ.',body)
figs=[('two_curves','Hai đường ngang hàng','Cùng đỏ, cùng nét chính; liền/đứt và chú giải phân đối tượng.'),('geometry_3d','Khối và mặt đang xét','Biên khối xám cùng cấp nét với đường cong; mặt trên đang xét dùng đỏ. Vàng nhạt chỉ mặt phụ trợ, không biến mọi mặt thành điểm nhấn.'),('geometry_2d','Hai đoạn và góc','Đường trọng tâm và cung góc cùng họ đỏ; nhãn STIX giữ cùng cỡ với các hình khác.'),('geometry_sphere','Mặt cầu và đường tròn','Đường tròn trọng tâm đỏ, khối nền và nét khuất xám. Không làm mất ý nghĩa thấy/khuất khi đổi màu.'),('inverse','Hai nhánh, một hàm','Tập xác định giữ hai phần; đường không nối qua điểm loại.'),('disconnected','Điểm hở và phản ví dụ','Hở/đặc vẫn là kí hiệu toán, không đổi theo sở thích trang trí.'),('hole','Điểm bị loại','Lỗ giữ đúng tọa độ, nền trong điểm hở trùng trường hình.'),('area','Miền cần quan sát','Vàng nhạt đặt trên diện tích; đỏ giữ đường biên cần xét.'),('absolute','Góc gãy','Hai nét gặp đúng ở gốc; không làm tròn hình học theo bán kính giao diện.'),('data_frequency','Biểu đồ dữ liệu','Dữ liệu giả lập 50 bài; nhãn và trục giữ nghĩa số lượng. Cùng một đại lượng không tự sinh nhiều màu.')]
body='<div class="rule-list"><div><strong>Trường hình</strong><p>Giấy #FBFAF8, khung #DFD7CA 0,45 pt, khoảng thở 5 mm; không dùng nền vàng như mặc định riêng của đồ thị.</p></div><div><strong>Hệ nét</strong><p>Nét đối tượng 1,1 pt; cấu trúc 0,8 pt; hỗ trợ 0,6–0,7 pt. Nét khuất là trạng thái hình học; đường phụ là vai trò suy luận.</p></div><div><strong>Hệ chú thích</strong><p>STIX, nhãn đọc cùng thang cỡ; điểm hở/đặc và kiểu nét giữ nghĩa khi mất màu. Chỉ tô vàng khi có một miền hay mặt cần đọc.</p></div></div><div class="gallery-grid">'+''.join(card(title,img(f'graphics/{id}.svg',title)+f'<p class="asset-links">{dl("graphics/"+id+".svg","SVG")}{dl("graphics/"+id+".pdf","PDF vector")}</p>',whytext,'Style và compiler trong repo, thích ứng qua một bảng vai trò 0.4') for id,title,whytext in figs)+'</div>'
panel('math','Một ngôn ngữ cho các hình toán.','Nhất quán nằm ở vai trò nét, chữ và điểm nhấn. Hình học vẫn giữ chiều sâu; đồ thị vẫn giữ hệ trục.',body)
